cd /workspace/submission && cat > plan.hpp <<'EOF'
#pragma once
// Exact cache-budgeted layout planner.
//
// For every version the planner minimises the published scalarised pair
//   work * 2^16 + image_pages
// which is exactly lexicographic (minimum work, then minimum pages) because
// every legal request stays far below 2^16 total pages.  The interval dynamic
// program carries the resident-page budget so that tree topology, node
// encoding and residency are chosen jointly, and the per-case budget is then
// shared across all immutable versions by a small knapsack.
#include <algorithm>
#include <cstdint>
#include <stdexcept>
#include <string>
#include <vector>
#include "engine.hpp"

static const i128 PLAN_BIG = (i128)1 << 16;
static const i128 PLAN_INF = (i128)1 << 120;

struct PlanBurst { long long repeat; std::vector<int> idx; };
struct PlanVer {
    int R;
    std::vector<Key> starts;
    std::vector<long long> hops;
    std::vector<PlanBurst> bursts;
};
struct PlanCosts { int C; long long hit, miss; long long dec[3]; };

struct PlanDec {
    int mode, cached, b, P;
    std::vector<int> cuts;   // child boundaries, size b+1 (internal only)
    std::vector<int> buds;   // child budgets, size b
};

struct VersionPlan {
    std::vector<i128> dp;    // (i*(R+1)+j)*(C+1)+c
    std::vector<PlanDec> dec;
    std::vector<i128> phi;   // C+1 scalarised optima for budgets 0..C
    int R, C;
};

struct Opt {
    int b, mode, P;
    long long coeff;
};

static inline long long plan_ceil_div(long long a, long long b) { return (a + b - 1) / b; }

static std::vector<Opt> interval_options(const std::vector<Key>& starts, int i, int j,
                                         const PlanCosts& pc) {
    std::vector<Opt> out;
    int len = j - i;
    Key spread = starts[j - 1] - starts[i];
    bool ok1 = spread < (((Key)1) << 64);
    bool ok2 = spread < (((Key)1) << 32);
    for (int mode = 0; mode < 3; ++mode) {
        if (mode == 1 && !ok1) continue;
        if (mode == 2 && !ok2) continue;
        if (len <= 8) {
            unsigned k = (unsigned)len;
            unsigned used = 32u + k * (unsigned)IMG_WIDTH[mode];
            Opt o; o.b = 0; o.mode = mode; o.P = (int)((used + 63u) / 64u);
            o.coeff = plan_ceil_div((long long)k, IMG_LANES[mode]) + pc.dec[mode];
            out.push_back(o);
        }
        int bmax = std::min(9, len);
        for (int b = 2; b <= bmax; ++b) {
            unsigned k = (unsigned)(b - 1);
            unsigned used = 32u + 4u * (unsigned)b + k * (unsigned)IMG_WIDTH[mode];
            Opt o; o.b = b; o.mode = mode; o.P = (int)((used + 63u) / 64u);
            o.coeff = plan_ceil_div((long long)k, IMG_LANES[mode]) + pc.dec[mode];
            out.push_back(o);
        }
    }
    return out;
}

static VersionPlan plan_version(const PlanVer& v, const PlanCosts& pc) {
    int R = v.R, C = pc.C;
    if (R < 1 || R > 64) throw std::runtime_error("plan runs");
    std::vector<i128> Q((size_t)R * R, 0), T((size_t)R * R, 0);
    // burst run-index histograms -> exact Q[i][j], T[i][j]
    for (size_t bi = 0; bi < v.bursts.size(); ++bi) {
        const PlanBurst& b = v.bursts[bi];
        std::vector<int> cnt((size_t)R + 1, 0);
        for (int i = 0; i <= R; ++i) {
            int n = 0;
            for (size_t k = 0; k < b.idx.size(); ++k) if (b.idx[k] < i) ++n;
            cnt[(size_t)i] = n;
        }
        for (int i = 0; i < R; ++i)
            for (int j = i + 1; j <= R; ++j) {
                Q[(size_t)i * R + j] += (i128)b.repeat * (cnt[(size_t)j] - cnt[(size_t)i]);
                if (cnt[(size_t)j] > cnt[(size_t)i]) T[(size_t)i * R + j] += (i128)b.repeat;
            }
    }
    size_t W = (size_t)(C + 1);
    size_t S = (size_t)(R + 1) * (R + 1) * W;
    VersionPlan vp;
    vp.R = R; vp.C = C;
    vp.dp.assign(S, PLAN_INF);
    vp.dec.resize(S);
    std::vector<std::vector<Opt> > opts((size_t)R * R);
    std::vector<i128> wcost0((size_t)R * R), wcost1((size_t)R * R);   // uncached/cached base
    for (int i = 0; i < R; ++i)
        for (int j = i + 1; j <= R; ++j) {
            opts[(size_t)i * R + j] = interval_options(v.starts, i, j, pc);
            wcost0[(size_t)i * R + j] = T[(size_t)i * R + j] * pc.miss;
            wcost1[(size_t)i * R + j] = T[(size_t)i * R + j] * pc.hit;
        }
    bool caching_helps = pc.miss > pc.hit;
    // chain[b][t][c] for the fixed left end i
    std::vector<i128> chain(10 * (size_t)(R + 1) * W);
    std::vector<int> argk(10 * (size_t)(R + 1) * W), argc(10 * (size_t)(R + 1) * W);
#define DPAT(i,j,c) vp.dp[((size_t)(i) * (R + 1) + (j)) * W + (c)]
#define DECAT(i,j,c) vp.dec[((size_t)(i) * (R + 1) + (j)) * W + (c)]
#define CH(b,t,c) chain[((size_t)(b) * (R + 1) + (t)) * W + (c)]
#define CK(b,t,c) argk[((size_t)(b) * (R + 1) + (t)) * W + (c)]
#define CC(b,t,c) argc[((size_t)(b) * (R + 1) + (t)) * W + (c)]
    for (int i = R - 1; i >= 0; --i) {
        std::fill(chain.begin(), chain.end(), PLAN_INF);
        std::fill(argk.begin(), argk.end(), -1);
        std::fill(argc.begin(), argc.end(), 0);
        for (int t = i + 1; t <= R; ++t) {
            int L = t - i;
            int cmax = std::min(C, 4 * (2 * L - 1));
            // partitions of [i,t) into b>=2 consecutive subtrees
            int bmax = std::min(9, L);
            for (int b = 2; b <= bmax; ++b) {
                for (int c = 0; c <= cmax; ++c) {
                    i128 best = PLAN_INF; int bk = -1, bc = 0;
                    for (int k = i + b - 1; k <= t - 1; ++k) {
                        int L1 = k - i, L2 = t - k;
                        int cap1 = std::min(cmax, std::min(C, 4 * (2 * L1 - 1)));
                        int cap2 = std::min(C, 4 * (2 * L2 - 1));
                        int lo = std::max(0, c - cap2), hi = std::min(c, cap1);
                        for (int c1 = lo; c1 <= hi; ++c1) {
                            i128 a = CH(b - 1, k, c1);
                            if (a >= PLAN_INF) continue;
                            i128 d = DPAT(k, t, c - c1);
                            if (d >= PLAN_INF) continue;
                            i128 val = a + d;
                            if (val < best) { best = val; bk = k; bc = c1; }
                        }
                    }
                    CH(b, t, c) = best; CK(b, t, c) = bk; CC(b, t, c) = bc;
                }
            }
            const std::vector<Opt>& os = opts[(size_t)i * R + t];
            i128 wc0 = wcost0[(size_t)i * R + t];
            i128 wc1 = wcost1[(size_t)i * R + t];
            for (int c = 0; c <= cmax; ++c) {
                i128 best = PLAN_INF; PlanDec bd; bd.mode = 0; bd.cached = 0; bd.b = 0; bd.P = 1;
                for (size_t oi = 0; oi < os.size(); ++oi) {
                    const Opt& o = os[oi];
                    for (int cached = 0; cached < 2; ++cached) {
                        if (cached && (!caching_helps || o.P > c)) continue;
                        if (!cached && !caching_helps && cached) continue;
                        i128 work = (cached ? wc1 : wc0) * o.P + (i128)o.coeff * Q[(size_t)i * R + t];
                        i128 val = work * PLAN_BIG + o.P;
                        int rest = c - (cached ? o.P : 0);
                        if (o.b == 0) {
                            val += 0;
                        } else {
                            i128 sub = CH(o.b, t, std::min(rest, cmax));
                            if (sub >= PLAN_INF) continue;
                            val += sub;
                        }
                        if (val < best) {
                            best = val;
                            bd.mode = o.mode; bd.cached = cached; bd.b = o.b; bd.P = o.P;
                            bd.cuts.clear(); bd.buds.clear();
                            if (o.b) {
                                int tcur = t, bcur = o.b, ccur = rest;
                                std::vector<int> st, en, bud;
                                while (bcur > 1) {
                                    int k = CK(bcur, tcur, std::min(ccur, cmax));
                                    if (k < 0) { st.clear(); break; }
                                    int c1 = CC(bcur, tcur, std::min(ccur, cmax));
                                    st.push_back(k); en.push_back(tcur); bud.push_back(ccur - c1);
                                    tcur = k; bcur -= 1; ccur = c1;
                                }
                                if (!st.empty()) {
                                    st.push_back(i); en.push_back(tcur); bud.push_back(ccur);
                                    std::reverse(st.begin(), st.end());
                                    std::reverse(en.begin(), en.end());
                                    std::reverse(bud.begin(), bud.end());
                                    bd.cuts.push_back(i);
                                    for (size_t z = 0; z < st.size(); ++z) {
                                        if (bd.cuts.back() != st[z]) { bd.cuts.clear(); bd.buds.clear(); break; }
                                        bd.cuts.push_back(en[z]); bd.buds.push_back(bud[z]);
                                    }
                                }
                                if (bd.cuts.empty()) { val = PLAN_INF; continue; }
                            }
                        }
                    }
                }
                DPAT(i, t, c) = best;
                DECAT(i, t, c) = bd;
                if (best >= PLAN_INF) throw std::runtime_error("plan infeasible");
            }
            for (int c = cmax + 1; c <= C; ++c) {
                DPAT(i, t, c) = DPAT(i, t, cmax);
                DECAT(i, t, c) = DECAT(i, t, cmax);
            }
            for (int c = 0; c <= C; ++c) CH(1, t, c) = DPAT(i, t, c);
        }
    }
#undef DPAT
#undef DECAT
#undef CH
#undef CK
#undef CC
    vp.phi.assign((size_t)C + 1, PLAN_INF);
    for (int c = 0; c <= C; ++c) {
        i128 pages = 1 + (4 * (i128)R + 63) / 64;
        vp.phi[(size_t)c] = DPAT2(0, R, c) + pages;
    }
    return vp;
}
#define DPAT2(vp, i, j, c) (vp).dp[((size_t)(i) * ((vp).R + 1) + (j)) * ((vp).C + 1) + (c)]

static void reconstruct(const VersionPlan& vp, int i, int j, int c, std::vector<Layout>& out) {
    const PlanDec& d = vp.dec[((size_t)i * (vp.R + 1) + j) * (vp.C + 1) + c];
    Layout n; n.lo = i; n.span = j - i; n.mode = d.mode; n.cached = d.cached;
    size_t self = out.size();
    out.push_back(n);
    for (int z = 0; z + 1 < (int)d.cuts.size(); ++z)
        reconstruct(vp, d.cuts[z], d.cuts[z + 1], d.buds[z], out);
    for (int z = 0; z + 1 < (int)d.cuts.size(); ++z)
        out[self].children.push_back((int)(self + 1 + z));
}
